/* Spring Quick Read Book - reader UI.
 *
 * Works two ways:
 *   1. Opened straight from disk (file://) - chapter text comes from
 *      assets/chapters-data.js, generated by build.py.
 *   2. Served over http:// - chapters are fetched fresh from chapters/*.md,
 *      so edits show up on reload without re-running build.py.
 */
(function () {
  'use strict';

  /* Distinct from the Java book's keys so the two share a file:// origin
     without clobbering each other's progress. */
  var STORE_READ  = 'springBook.read.v1';
  var STORE_THEME = 'springBook.theme.v1';
  var STORE_LAST  = 'springBook.lastChapter.v1';

  var chapters = (window.CHAPTERS_DATA || []).slice();
  var readState = load(STORE_READ, {});
  var currentId = null;
  var rendered = {};      // id -> html (render once, then cache)
  var headingObserver = null;

  var $ = function (id) { return document.getElementById(id); };
  var el = {
    list: $('chapter-list'), chapter: $('chapter'), loading: $('loading'),
    tocList: $('toc-list'), toc: $('toc'), nav: $('chapter-nav'),
    prev: $('prev-btn'), next: $('next-btn'), read: $('read-btn'),
    fill: $('progress-fill'), label: $('progress-label'),
    search: $('search'), clear: $('search-clear'), results: $('search-results'),
    sidebar: $('sidebar'), sidebarToggle: $('sidebar-toggle'),
    sidebarFoot: $('sidebar-foot'),
    theme: $('theme-toggle'), toTop: $('to-top'),
    markAll: $('mark-all'), reset: $('reset-progress'),
    hljsLight: $('hljs-light'), hljsDark: $('hljs-dark')
  };

  /* -------------------------------------------------------------- storage */
  function load(key, fallback) {
    try { return JSON.parse(localStorage.getItem(key)) || fallback; }
    catch (e) { return fallback; }
  }
  function save(key, value) {
    try { localStorage.setItem(key, JSON.stringify(value)); } catch (e) { /* private mode */ }
  }

  /* ---------------------------------------------------------------- theme */
  function applyTheme(theme) {
    document.documentElement.setAttribute('data-theme', theme);
    if (el.hljsLight) el.hljsLight.disabled = theme === 'dark';
    if (el.hljsDark)  el.hljsDark.disabled  = theme !== 'dark';
    el.theme.textContent = theme === 'dark' ? '☀' : '◐';
    save(STORE_THEME, theme);
  }
  applyTheme(load(STORE_THEME, null) ||
    (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'));
  el.theme.addEventListener('click', function () {
    applyTheme(document.documentElement.getAttribute('data-theme') === 'dark' ? 'light' : 'dark');
  });

  /* -------------------------------------------------------------- markdown */
  /* Heading text arrives as rendered HTML ("<code>&lt;T&gt;</code>"), so strip
     tags AND decode entities before slugifying - otherwise "&lt;" turns into
     the letters "lt" and the slug stops matching the links the chapters use. */
  function plainText(html) {
    var d = document.createElement('div');
    d.innerHTML = String(html);
    return (d.textContent || '').replace(/\s+/g, ' ').trim();
  }

  /* Mirror GitHub's slugger, because that is what the chapters' own
     "Table of Contents" links assume. Note it does NOT collapse runs of
     hyphens or trim trailing ones: "Memory & GC Review" -> "memory--gc-review". */
  function slugify(text) {
    return String(text).toLowerCase()
      .replace(/[^\w\- ]+/g, '')
      .replace(/ /g, '-');
  }

  function configureMarked() {
    if (!window.marked) return;
    var renderer = new marked.Renderer();
    var seen = {};

    renderer.heading = function (text, level) {
      var plain = plainText(text);
      var base = slugify(plain) || 'section';
      var slug = base;
      var n = 0;
      while (seen[slug]) { slug = base + '-' + (++n); }   // GitHub starts at -1
      seen[slug] = true;
      var anchor = level === 2 || level === 3
        ? ' <a class="anchor" href="#' + currentId + '/' + slug + '" aria-label="Link to this section">#</a>'
        : '';
      return '<h' + level + ' id="' + slug + '" data-title="' + escapeHtml(plain) + '">' +
             text + anchor + '</h' + level + '>';
    };

    renderer.code = function (code, infostring) {
      var lang = (infostring || '').match(/\S*/)[0].toLowerCase();
      var alias = { sh: 'bash', shell: 'bash', console: 'bash', text: 'plaintext',
                    html: 'xml', pom: 'xml', gradle: 'groovy', kts: 'kotlin',
                    'gradle.kts': 'kotlin', toml: 'ini', jshell: 'java',
                    // Spring-flavoured fences that hljs has no grammar for.
                    yml: 'yaml', jsonc: 'json', json5: 'json',
                    env: 'properties', conf: 'properties', cfg: 'properties',
                    dockerfile: 'dockerfile', docker: 'dockerfile',
                    compose: 'yaml', k8s: 'yaml', kubernetes: 'yaml',
                    jpql: 'sql', hql: 'sql', promql: 'plaintext',
                    curl: 'bash', cron: 'plaintext', ascii: 'plaintext' };
      lang = alias[lang] || lang;
      var out;
      if (window.hljs && lang && hljs.getLanguage(lang)) {
        try { out = hljs.highlight(code, { language: lang, ignoreIllegals: true }).value; }
        catch (e) { out = escapeHtml(code); }
      } else {
        out = escapeHtml(code);
      }
      return '<pre><button class="copy-btn" type="button">Copy</button>' +
             '<code class="hljs' + (lang ? ' language-' + lang : '') + '">' + out + '</code></pre>';
    };

    marked.setOptions({ renderer: renderer, gfm: true, breaks: false, mangle: false, headerIds: false });
    configureMarked.resetSeen = function () { seen = {}; };
  }

  function escapeHtml(s) {
    return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;')
      .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  /* Fallback renderer if the CDN is unreachable: show the raw markdown
     rather than a blank page. */
  function renderMarkdown(md) {
    if (!window.marked) {
      return '<div class="chapter-meta"><span class="pill">Offline: showing raw Markdown ' +
             '(highlighting needs an internet connection)</span></div>' +
             '<pre><code>' + escapeHtml(md) + '</code></pre>';
    }
    if (configureMarked.resetSeen) configureMarked.resetSeen();
    return marked.parse(md);
  }

  /* -------------------------------------------------------------- sidebar */
  function buildSidebar() {
    el.list.innerHTML = '';
    chapters.forEach(function (ch) {
      var li = document.createElement('li');
      li.className = 'chapter-item';
      li.dataset.id = ch.id;

      var box = document.createElement('input');
      box.type = 'checkbox';
      box.className = 'chapter-check';
      box.checked = !!readState[ch.id];
      box.title = 'Mark chapter as read';
      box.setAttribute('aria-label', 'Mark "' + ch.title + '" as read');
      box.addEventListener('change', function () { setRead(ch.id, box.checked); });

      var link = document.createElement('button');
      link.type = 'button';
      link.className = 'chapter-link';
      link.innerHTML = '<span class="ch-num">' + (ch.number || '•') + '</span>' +
                       '<span class="ch-title"></span>';
      link.querySelector('.ch-title').textContent = ch.title;
      link.addEventListener('click', function () { openChapter(ch.id, true); });

      li.appendChild(box);
      li.appendChild(link);
      el.list.appendChild(li);
    });

    el.sidebarFoot.innerHTML =
      '<kbd>/</kbd> search &nbsp; <kbd>[</kbd> <kbd>]</kbd> prev/next &nbsp; ' +
      '<kbd>m</kbd> mark read<br>Progress is saved in this browser.';

    refreshSidebarState();
  }

  function refreshSidebarState() {
    Array.prototype.forEach.call(el.list.children, function (li) {
      var isRead = !!readState[li.dataset.id];
      li.classList.toggle('read', isRead);
      li.classList.toggle('active', li.dataset.id === currentId);
      li.querySelector('.chapter-check').checked = isRead;
    });
    updateProgress();
  }

  function updateProgress() {
    var total = chapters.length;
    var done = chapters.filter(function (c) { return readState[c.id]; }).length;
    el.fill.style.width = total ? (done / total * 100) + '%' : '0%';
    el.label.textContent = done + ' / ' + total;
  }

  function setRead(id, value) {
    if (value) readState[id] = true; else delete readState[id];
    save(STORE_READ, readState);
    refreshSidebarState();
    if (id === currentId) updateReadButton();
  }

  function updateReadButton() {
    var isRead = !!readState[currentId];
    el.read.classList.toggle('is-read', isRead);
    el.read.textContent = isRead ? '✓ Read — click to unmark' : 'Mark as read';
    var pill = el.chapter.querySelector('.js-read-pill');
    if (pill) {
      pill.classList.toggle('done', isRead);
      pill.textContent = isRead ? '✓ Read' : 'Not read yet';
    }
  }

  /* ------------------------------------------------------------- chapters */
  function indexOfId(id) {
    for (var i = 0; i < chapters.length; i++) if (chapters[i].id === id) return i;
    return -1;
  }

  function metaStrip(ch) {
    var minutes = Math.max(1, Math.round(ch.words / 220));
    return '<div class="chapter-meta">' +
      '<span class="pill">Chapter ' + (ch.number || '–') + ' of ' + chapters.length + '</span>' +
      '<span class="pill">' + ch.words.toLocaleString() + ' words · ~' + minutes + ' min</span>' +
      '<span class="pill js-read-pill"></span>' +
      '</div>';
  }

  function openChapter(id, pushHash, anchor) {
    var i = indexOfId(id);
    if (i < 0) return;
    var ch = chapters[i];
    currentId = id;
    save(STORE_LAST, id);

    if (!rendered[id]) rendered[id] = renderMarkdown(ch.markdown);

    // Meta strip goes after the <h1> so the title stays first.
    var html = rendered[id];
    var h1End = html.indexOf('</h1>');
    el.chapter.innerHTML = h1End > -1
      ? html.slice(0, h1End + 5) + metaStrip(ch) + html.slice(h1End + 5)
      : metaStrip(ch) + html;

    tidyInPageToc();
    wireCopyButtons();
    wireInternalLinks();
    buildToc();
    updateNav(i);
    updateReadButton();
    refreshSidebarState();
    closeSearch(false);
    el.nav.hidden = false;
    el.sidebar.classList.remove('open');

    if (pushHash) {
      history.replaceState(null, '', '#' + id + (anchor ? '/' + anchor : ''));
    }

    if (anchor) {
      var target = document.getElementById(anchor);
      if (target) { target.scrollIntoView(); return; }
    }
    window.scrollTo(0, 0);

    var active = el.list.querySelector('.chapter-item.active');
    if (active && active.scrollIntoView) {
      active.scrollIntoView({ block: 'nearest' });
    }
  }

  function updateNav(i) {
    var prev = chapters[i - 1], next = chapters[i + 1];
    el.prev.disabled = !prev;
    el.next.disabled = !next;
    el.prev.textContent = prev ? '← ' + (prev.number ? prev.number + '. ' : '') + prev.title : '← Previous';
    el.next.textContent = next ? (next.number ? next.number + '. ' : '') + next.title + ' →' : 'Next →';
    el.prev.onclick = prev ? function () { openChapter(prev.id, true); } : null;
    el.next.onclick = next ? function () { openChapter(next.id, true); } : null;
  }

  el.read.addEventListener('click', function () { setRead(currentId, !readState[currentId]); });

  el.markAll.addEventListener('click', function () {
    var allRead = chapters.every(function (c) { return readState[c.id]; });
    chapters.forEach(function (c) {
      if (allRead) delete readState[c.id]; else readState[c.id] = true;
    });
    save(STORE_READ, readState);
    refreshSidebarState();
    updateReadButton();
  });

  el.reset.addEventListener('click', function () {
    if (!confirm('Clear read progress for all chapters?')) return;
    readState = {};
    save(STORE_READ, readState);
    refreshSidebarState();
    updateReadButton();
  });

  /* Chapters open with their own bullet-list table of contents. The right-hand
     rail already shows that, so collapse the in-page copy into a one-line
     <details> instead of making the reader scroll past it. */
  function tidyInPageToc() {
    var kids = Array.prototype.slice.call(el.chapter.children);
    var label = null, list = null;

    for (var i = 0; i < kids.length; i++) {
      var node = kids[i];
      var tag = node.tagName;
      // The "#" anchor link is part of textContent, so normalise it away.
      var text = (node.textContent || '').toLowerCase()
        .replace(/[^a-z ]/g, '').replace(/\s+/g, ' ').trim();
      var isTocLabel = text === 'table of contents' || text === 'contents';

      if (tag === 'H2' || tag === 'H3') {
        if (isTocLabel) { label = node; continue; }
        break;                      // real content started - no leading TOC
      }
      if (tag === 'P' && isTocLabel) { label = node; continue; }
      if (tag === 'UL') {
        var all = node.querySelectorAll('a');
        var internal = node.querySelectorAll('a[href^="#"]');
        if (all.length >= 3 && all.length === internal.length) { list = node; }
        break;                      // first list decides it either way
      }
    }
    if (!list) return;

    var details = document.createElement('details');
    details.className = 'in-page-toc';
    var summary = document.createElement('summary');
    summary.textContent = 'Chapter contents';
    details.appendChild(summary);

    list.parentNode.insertBefore(details, list);
    details.appendChild(list);
    if (label) label.parentNode.removeChild(label);
  }

  /* Keep the chapter id in the hash when following an in-chapter link, so a
     reload lands back on the same chapter rather than the first one. */
  function wireInternalLinks() {
    var links = el.chapter.querySelectorAll('a[href^="#"]:not(.anchor)');
    Array.prototype.forEach.call(links, function (a) {
      var slug = a.getAttribute('href').slice(1);
      if (!slug || slug.indexOf('/') > -1) return;
      a.addEventListener('click', function (e) {
        var target = document.getElementById(slug);
        if (!target) return;                       // let the browser try
        e.preventDefault();
        target.scrollIntoView();
        history.replaceState(null, '', '#' + currentId + '/' + slug);
      });
    });
  }

  /* ------------------------------------------------------------------ toc */
  function buildToc() {
    el.tocList.innerHTML = '';
    var heads = el.chapter.querySelectorAll('h2, h3');
    if (!heads.length) { el.toc.style.visibility = 'hidden'; return; }
    el.toc.style.visibility = 'visible';

    Array.prototype.forEach.call(heads, function (h) {
      var li = document.createElement('li');
      li.className = 'lvl-' + h.tagName[1];
      var a = document.createElement('a');
      a.href = '#' + currentId + '/' + h.id;
      a.textContent = h.dataset.title || h.textContent.replace(/#$/, '').trim();
      a.dataset.target = h.id;
      a.addEventListener('click', function (e) {
        e.preventDefault();
        h.scrollIntoView();
        history.replaceState(null, '', '#' + currentId + '/' + h.id);
      });
      li.appendChild(a);
      el.tocList.appendChild(li);
    });

    if (headingObserver) headingObserver.disconnect();
    if (!('IntersectionObserver' in window)) return;

    headingObserver = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (!entry.isIntersecting) return;
        var links = el.tocList.querySelectorAll('a');
        Array.prototype.forEach.call(links, function (a) {
          a.classList.toggle('active', a.dataset.target === entry.target.id);
        });
      });
    }, { rootMargin: '-70px 0px -75% 0px', threshold: 0 });

    Array.prototype.forEach.call(heads, function (h) { headingObserver.observe(h); });
  }

  /* ----------------------------------------------------------------- copy */
  function wireCopyButtons() {
    var btns = el.chapter.querySelectorAll('.copy-btn');
    Array.prototype.forEach.call(btns, function (btn) {
      btn.addEventListener('click', function () {
        var code = btn.parentNode.querySelector('code');
        var text = code ? code.textContent : '';
        var done = function () {
          btn.textContent = 'Copied';
          btn.classList.add('copied');
          setTimeout(function () { btn.textContent = 'Copy'; btn.classList.remove('copied'); }, 1400);
        };
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(text).then(done, function () {});
        } else {
          var ta = document.createElement('textarea');
          ta.value = text; document.body.appendChild(ta); ta.select();
          try { document.execCommand('copy'); done(); } catch (e) { /* ignore */ }
          document.body.removeChild(ta);
        }
      });
    });
  }

  /* --------------------------------------------------------------- search */
  var searchTimer = null;

  el.search.addEventListener('input', function () {
    clearTimeout(searchTimer);
    searchTimer = setTimeout(runSearch, 130);
  });
  el.clear.addEventListener('click', function () { el.search.value = ''; closeSearch(true); });

  function closeSearch(clearInput) {
    if (clearInput) el.search.value = '';
    el.results.hidden = true;
    el.results.innerHTML = '';
    el.clear.hidden = !el.search.value;
    Array.prototype.forEach.call(el.list.children, function (li) {
      li.classList.remove('hidden');
      var hit = li.querySelector('.ch-hits');
      if (hit) hit.remove();
    });
  }

  function runSearch() {
    var q = el.search.value.trim();
    el.clear.hidden = !q;
    if (q.length < 2) { closeSearch(false); return; }

    var needle = q.toLowerCase();
    var matches = [];

    chapters.forEach(function (ch) {
      var hay = ch.markdown.toLowerCase();
      var body = contentStart(ch.markdown);
      var count = 0, from = 0, first = -1, inBody = -1, idx;
      while ((idx = hay.indexOf(needle, from)) !== -1) {
        if (first === -1) first = idx;
        if (inBody === -1 && idx >= body) inBody = idx;
        count++; from = idx + needle.length;
        if (count > 500) break;
      }
      // Skip hits inside the chapter's own contents list - jumping there
      // tells the reader nothing.
      if (inBody !== -1) first = inBody;
      var titleHit = ch.title.toLowerCase().indexOf(needle) !== -1;
      if (count || titleHit) {
        matches.push({ ch: ch, count: count, at: first, titleHit: titleHit });
      }
    });

    matches.sort(function (a, b) {
      if (a.titleHit !== b.titleHit) return a.titleHit ? -1 : 1;
      return b.count - a.count;
    });

    // Sidebar: keep only matching chapters, badge them with hit counts.
    var ids = {};
    matches.forEach(function (m) { ids[m.ch.id] = m.count; });
    Array.prototype.forEach.call(el.list.children, function (li) {
      var has = Object.prototype.hasOwnProperty.call(ids, li.dataset.id);
      li.classList.toggle('hidden', !has);
      var badge = li.querySelector('.ch-hits');
      if (badge) badge.remove();
      if (has && ids[li.dataset.id]) {
        var b = document.createElement('span');
        b.className = 'ch-hits';
        b.textContent = ids[li.dataset.id];
        li.querySelector('.chapter-link').appendChild(b);
      }
    });

    // Results panel above the chapter body.
    el.results.hidden = false;
    if (!matches.length) {
      el.results.innerHTML = '<div class="sr-head">Search</div>' +
        '<p class="sr-empty">No matches for “' + escapeHtml(q) + '”.</p>';
      return;
    }

    var total = matches.reduce(function (n, m) { return n + m.count; }, 0);
    var frag = document.createElement('div');
    frag.innerHTML = '<div class="sr-head">' + total + ' match' + (total === 1 ? '' : 'es') +
                     ' in ' + matches.length + ' chapter' + (matches.length === 1 ? '' : 's') + '</div>';

    matches.slice(0, 25).forEach(function (m) {
      var btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'sr-item';
      btn.innerHTML = '<div class="sr-title">' +
          escapeHtml((m.ch.number ? m.ch.number + '. ' : '') + m.ch.title) +
          ' <span class="count">' + (m.count ? m.count + ' hit' + (m.count === 1 ? '' : 's') : 'title match') +
          '</span></div>' +
        '<div class="sr-snippet">' + snippet(m.ch.markdown, m.at, needle.length) + '</div>';
      btn.addEventListener('click', function () {
        openChapter(m.ch.id, true, headingNear(m.ch.markdown, m.at));
      });
      frag.appendChild(btn);
    });

    el.results.innerHTML = '';
    while (frag.firstChild) el.results.appendChild(frag.firstChild);
  }

  function snippet(md, at, len) {
    if (at < 0) return '';
    var start = Math.max(0, at - 90);
    var end = Math.min(md.length, at + len + 130);
    var text = (start > 0 ? '…' : '') + md.slice(start, end).replace(/\s+/g, ' ') + (end < md.length ? '…' : '');
    var pos = text.toLowerCase().indexOf(md.slice(at, at + len).toLowerCase());
    if (pos < 0) return escapeHtml(text);
    return escapeHtml(text.slice(0, pos)) +
           '<mark>' + escapeHtml(text.slice(pos, pos + len)) + '</mark>' +
           escapeHtml(text.slice(pos + len));
  }

  /* Where the chapter body really begins - i.e. past its own contents list. */
  function contentStart(md) {
    var re = /\n##\s+([^\n]+)/g, m;
    while ((m = re.exec(md)) !== null) {
      if (!/^(table of )?contents$/i.test(m[1].trim())) return m.index + 1;
    }
    return 0;
  }

  /* Nearest ## / ### heading above the match, so search results land close by. */
  function headingNear(md, at) {
    if (at < 0) return null;
    var lines = md.slice(0, at).split('\n');
    for (var i = lines.length - 1; i >= 0; i--) {
      var h = lines[i].match(/^#{2,3}\s+(.+?)\s*$/);
      if (h) {
        var title = h[1].replace(/`/g, '');
        if (/^(table of )?contents$/i.test(title)) return null;
        return slugify(title);
      }
    }
    return null;
  }

  /* -------------------------------------------------------------- routing */
  function fromHash() {
    var raw = location.hash.replace(/^#/, '');
    if (!raw) return null;
    var parts = raw.split('/');
    return { id: decodeURIComponent(parts[0]), anchor: parts[1] ? decodeURIComponent(parts[1]) : null };
  }

  window.addEventListener('hashchange', function () {
    var route = fromHash();
    if (route && route.id !== currentId && indexOfId(route.id) > -1) {
      openChapter(route.id, false, route.anchor);
    }
  });

  /* ------------------------------------------------------------ shortcuts */
  document.addEventListener('keydown', function (e) {
    var typing = /^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName);
    if (e.key === '/' && !typing) { e.preventDefault(); el.search.focus(); el.search.select(); return; }
    if (e.key === 'Escape' && typing) { el.search.blur(); closeSearch(true); return; }
    if (typing || e.metaKey || e.ctrlKey || e.altKey) return;
    if (e.key === '[') { if (!el.prev.disabled) el.prev.click(); }
    else if (e.key === ']') { if (!el.next.disabled) el.next.click(); }
    else if (e.key === 'm') { setRead(currentId, !readState[currentId]); }
  });

  el.sidebarToggle.addEventListener('click', function () { el.sidebar.classList.toggle('open'); });

  el.toTop.addEventListener('click', function () { window.scrollTo({ top: 0, behavior: 'smooth' }); });
  window.addEventListener('scroll', function () { el.toTop.hidden = window.scrollY < 500; });

  /* ----------------------------------------------------------------- boot */
  function boot() {
    if (!chapters.length) {
      el.loading.innerHTML = 'No chapters found. Run <code>python3 build.py</code> in the project root, ' +
                             'then reload this page.';
      return;
    }
    configureMarked();
    buildSidebar();
    var route = fromHash();
    var start = (route && indexOfId(route.id) > -1) ? route.id : (load(STORE_LAST, null) || chapters[0].id);
    if (indexOfId(start) < 0) start = chapters[0].id;
    openChapter(start, !route, route && route.anchor);
  }

  /* When served over http(s), prefer the live .md files so edits appear on
     reload. Falls back silently to the bundled copy. */
  function refreshFromDisk(done) {
    if (!/^https?:$/.test(location.protocol) || !window.fetch || !chapters.length) { done(); return; }
    var pending = chapters.length;
    var finish = function () { if (--pending === 0) done(); };
    chapters.forEach(function (ch) {
      fetch(ch.file, { cache: 'no-store' })
        .then(function (r) { return r.ok ? r.text() : null; })
        .then(function (text) {
          if (text && text.trim()) { ch.markdown = text; ch.words = text.split(/\s+/).length; }
          finish();
        })
        .catch(finish);
    });
  }

  refreshFromDisk(boot);
})();
